	nodes := make([]*TreeNode, len(tokens))
	for i, token := range tokens {
		if token != "null" {
			val, _ := strconv.Atoi(token)
			nodes[i] = &TreeNode{Val: val}
		}
	}
	child := 1
	for _, node := range nodes {
		if node == nil {
			continue
		}
		if child < len(nodes) {
			node.Left = nodes[child]
		}
		if child+1 < len(nodes) {
			node.Right = nodes[child+1]
		}
		child += 2
	}
	if len(nodes) == 0 {
		return nil
	}
	return nodes[0]
}

